function home(){const date=new Intl.DateTimeFormat('ar-OM-u-ca-islamic',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Muscat'}).format(new Date());const d=LIBRARY.find(d=>d.id==='d5'),v=QURAN?.[12].ayahs.find(a=>a.numberInSurah===28);$('#main').innerHTML=`<div class="date-line"><span><b>أهلًا بك في سكينة</b><i class="small-dot"></i>مساحة يأنس فيها قلبك</span><span>${date}</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">من عُمان… إلى قلبك</div><h1>حين يطمئن القلبُ<br><span>بذِكرِ الله.</span></h1><p>آية تتدبرها، ودعوة تبوح بها، وذكر يرافق يومك.<br>رحلتك إلى السكينة تبدأ بخطوة صغيرة.</p><div class="hero-buttons"><a class="btn" href="#quran">اقرأ القرآن الكريم <span>←</span></a><a class="btn secondary" href="#athkar/الصباح">أذكار الصباح ☼</a></div></div><div class="hero-art">${MOSQUE}<span class="hero-note">سَكِينَةٌ تَسْكُنُ الرُّوحَ</span></div></section><div class="section-head"><div><h2>أبوابٌ للسكينة</h2><p>اختر ما يحتاجه قلبك اليوم</p></div><a href="#duas">استكشف المكتبة ←</a></div><section class="paths" aria-label="أقسام الموقع">${[['athkar','☼','الأذكار اليومية','من إشراقة الصباح إلى هدوء المساء'],['duas','♧','الدعاء والرجاء','بين يدي الله، تبوح الروح'],['ruqyah','◇','الرقية الشرعية','آيات وأدعية، وتوكل على الله'],['names','۞','أسماء الله الحسنى','ولله الأسماء الحسنى فادعوه بها']].map(x=>`<a class="path" href="#${x[0]}"><span class="path-icon">${x[1]}</span><span class="arrow">↖</span><h3>${x[2]}</h3><p>${x[3]}</p></a>`).join('')}</section><section class="home-bottom"><article class="daily-card"><h3><span>♧</span> دعاء يلامس القلب <span class="tiny-label">دعاء قرآني</span></h3><p class="daily-text">${QURAN?esc(textOf(d)):'رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ'}</p><div class="card-meta">سورة القصص • الآية ٢٤ <a href="#duas?item=d5" style="float:left;color:var(--gold)">تأمل وادعُ ←</a></div></article><article class="verse-card"><h3>✦ وقفة مع آية</h3><p class="daily-text">${v?esc(v.text):'أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ'}</p><div class="card-meta">سورة الرعد • الآية ٢٨ <a href="#quran/13/28" style="float:left">اقرأ في سياقها ←</a></div></article></section><div class="section-head"><div><h2>قليلٌ دائم… أثرٌ عظيم</h2><p>عبادات القلب، وخيرٌ يمتد إلى الناس</p></div></div><div class="paths">${[['tasbih','◉','سبحتك بين يديك','عدّاد يحفظ ذكرك على جهازك'],['salawat','❧','الصلاة على النبي','محبة واتباع وصلاة وسلام'],['deeds','♧','أعمالك الصالحة','مساحة لمتابعة خير يومك'],['humility','♡','الرجاء والتذلل','باب التوبة والافتقار إلى الله']].map(x=>`<a class="path" href="#${x[0]}"><span class="path-icon">${x[1]}</span><h3>${x[2]}</h3><p>${x[3]}</p></a>`).join('')}</div><div class="notice">سكينة بروح عُمانية وهوية إباضية. نعتني بالمصدر، ونحيل المسائل الفقهية إلى أهل العلم. <a href="#sources" style="color:var(--gold)">تعرّف على منهج المحتوى ←</a></div>`}
function collection(route,category='الكل'){let items=route==='favorites'?LIBRARY.filter(d=>favorites.includes(d.id)):route==='humility'?LIBRARY.filter(d=>['d2','d3','d4','d5','d14','d17','d20','d23','d27','d28','d29','d34','d38'].includes(d.id)):LIBRARY.filter(d=>d.section===route);const categories=['الكل',...new Set(items.map(d=>d.category))];if(!categories.includes(category))category='الكل';const [title,desc]=TITLES[route];$('#main').innerHTML=heading(title,desc)+`${route==='ruqyah'?'<div class="notice">تُقرأ الرقية بكلام الله والدعاء المفهوم، مع اعتقاد أن الشفاء من الله. لا تتضمن هذه الصفحة تشخيصًا، ولا تغني الرقية عن الرعاية الطبية اللازمة. ما ورد بعدد مخصوص ذُكر مرجعه.</div>':''}${route==='athkar'?'<div class="notice">اختر وقت الذكر، واضغط العدّاد عند كل قراءة. الأذكار الحديثية معروضة بمراجعها، ولا تعني مراجعتها فقهيًا على المذهب الإباضي.</div>':''}<div class="toolbar"><label class="sr-only" for="collection-search">البحث في القسم</label><input id="collection-search" type="search" placeholder="ابحث في هذا القسم…"><button class="chip" id="font-down" aria-label="تصغير النص">أ−</button><button class="chip" id="font-up" aria-label="تكبير النص">أ+</button><button class="chip" id="reset-counts">تصفير عدّادات الجلسة</button></div><div class="toolbar" aria-label="تصنيف المحتوى">${categories.map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><p class="hint" id="result-total"></p><section class="content-grid" id="library-grid"></section>`;function show(query=''){const filtered=items.filter(d=>(category==='الكل'||d.category===category)&&normalize(d.title+' '+d.category+' '+textOf(d)).includes(normalize(query)));$('#result-total').textContent=ar(filtered.length)+' نصًا في هذا التصنيف';$('#library-grid').innerHTML=filtered.length?filtered.map(card).join(''):'<div class="empty">'+(route==='favorites'?'مفضلتك تنتظر أول ذكر. اضغط ☆ بجوار أي نص لحفظه.':'لا توجد نتائج. جرّب كلمة أخرى.')+'</div>'}show();$('#collection-search').addEventListener('input',e=>show(e.target.value));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{location.hash=route+'/'+encodeURIComponent(b.dataset.category)});$('#reset-counts').onclick=()=>{counts={};show($('#collection-search').value);toast('بدأت جلسة جديدة')};fontButtons()}
function fontButtons(){$('#font-up')?.addEventListener('click',()=>setFont(2));$('#font-down')?.addEventListener('click',()=>setFont(-2))}function setFont(delta){fontSize=Math.min(46,Math.max(22,fontSize+delta));document.documentElement.style.setProperty('--reading',fontSize+'px');write('font',fontSize)}
function renderQuran(snum=1,anum=0){if(!QURAN){$('#main').innerHTML=heading('المصحف الكريم',quranError?'تعذر تحميل المصحف.':'جارٍ فتح المصحف…')+(quranError?'<button class="btn" id="retry-quran">إعادة المحاولة</button>':'');$('#retry-quran')?.addEventListener('click',loadQuran);return}snum=Math.max(1,Math.min(114,Number(snum)||1));const s=QURAN[snum-1];$('#main').innerHTML=heading('المصحف الكريم','مصحف كامل بالرسم العثماني • ١١٤ سورة • ٦٬٢٣٦ آية','تلاوة وتدبر')+`<div class="toolbar">${bookmark?`<a class="btn secondary" href="#quran/${bookmark.s}/${bookmark.a}">تابع من علامتك • ${esc(QURAN[bookmark.s-1].name)} ${ar(bookmark.a)} ←</a>`:''}<label class="sr-only" for="quran-mobile-select">انتقل إلى سورة</label><select id="quran-mobile-select">${QURAN.map(s=>`<option value="${s.number}" ${s.number===snum?'selected':''}>${ar(s.number)} — ${esc(s.name)}</option>`).join('')}</select></div><div class="quran-layout"><aside class="surah-list" aria-label="فهرس السور"><label class="sr-only" for="surah-filter">بحث عن سورة</label><input type="search" id="surah-filter" placeholder="ابحث عن سورة…"><div class="surah-list-inner">${QURAN.map(s=>`<button class="surah-item ${s.number===snum?'active':''}" data-surah="${s.number}" data-name="${esc(normalize(s.name+' '+s.number))}"><span class="surah-num"><span>${ar(s.number)}</span></span><span class="surah-name">${esc(s.name)}<small>${s.revelationType==='Meccan'?'مكية':'مدنية'} • ${ar(s.ayahs.length)} آية</small></span></button>`).join('')}</div></aside><article class="mushaf"><div class="quran-controls"><span>حجم الخط</span><button id="font-down" aria-label="تصغير الخط">أ−</button><button id="font-up" aria-label="تكبير الخط">أ+</button><label for="verse-jump">الآية</label><select id="verse-jump">${s.ayahs.map(a=>`<option value="${a.numberInSurah}" ${a.numberInSurah===Number(anum)?'selected':''}>${ar(a.numberInSurah)}</option>`).join('')}</select><button id="go-verse">انتقل ←</button></div><div class="surah-title"><h2>${esc(s.name)}</h2><div class="card-meta">${s.revelationType==='Meccan'?'مكية':'مدنية'} • ${ar(s.ayahs.length)} آية</div></div><details><summary>استمع إلى السورة • مشاري العفاسي</summary><audio controls preload="none" src="https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/${snum}.mp3"></audio><p class="hint">التلاوة تحتاج اتصالًا بالإنترنت.</p></details><div id="ayahs">${s.ayahs.map(a=>`<div class="ayah ${bookmark?.s===snum&&bookmark?.a===a.numberInSurah?'bookmarked':''}" id="ayah-${a.numberInSurah}"><span>${esc(a.text)}</span> <span class="verse-number">﴿${ar(a.numberInSurah)}﴾</span><div class="ayah-tools"><button data-bookmark="${snum}:${a.numberInSurah}" aria-label="حفظ موضع القراءة عند الآية ${ar(a.numberInSurah)}">${bookmark?.s===snum&&bookmark?.a===a.numberInSurah?'◆':'◇'} علامة القراءة</button><button data-ayah-copy="${snum}:${a.numberInSurah}">نسخ الآية</button></div></div>`).join('')}</div><div class="pager">${snum>1?`<a class="btn secondary" href="#quran/${snum-1}">→ السورة السابقة</a>`:'<span></span>'}${snum<114?`<a class="btn secondary" href="#quran/${snum+1}">السورة التالية ←</a>`:''}</div><p class="reader-info">النص: Al Quran Cloud، إصدار quran-uthmani. <a href="#sources">المصادر والحقوق</a><br>النص محفوظ مع الموقع دون إعادة صياغة.</p></article></div>`;fontButtons();$('#surah-filter').oninput=e=>{document.querySelectorAll('.surah-item').forEach(b=>b.hidden=!b.dataset.name.includes(normalize(e.target.value)))};$('#quran-mobile-select').onchange=e=>location.hash='quran/'+e.target.value;$('#go-verse').onclick=()=>{location.hash=`quran/${snum}/${$('#verse-jump').value}`;setTimeout(()=>$('#ayah-'+$('#verse-jump').value)?.scrollIntoView({block:'center'}),0)};if(anum)setTimeout(()=>$('#ayah-'+Number(anum))?.scrollIntoView({block:'center'}),60)}
function namesPage(){$('#main').innerHTML=heading('ولله الأسماء الحسنى','تأمل أسماء الله، وادعُه بها.','معرفة ومحبة ورجاء')+'<div class="notice">هذه قائمة التسعة والتسعين المشهورة في التداول، وليست ادعاءً بأن ترتيبها أو جميع مفرداتها ثبتت في حديث واحد أو حُصرت فيها أسماء الله. للتفصيل العقدي والفقهي راجع أهل العلم ومكتب الإفتاء العُماني.</div><label class="sr-only" for="name-search">ابحث عن اسم</label><input type="search" id="name-search" placeholder="ابحث عن اسم…"><div class="names-grid" id="names-grid" style="margin-top:20px"></div>';function show(v=''){$('#names-grid').innerHTML=NAMES.map((name,i)=>({name,i})).filter(x=>normalize(x.name).includes(normalize(v))).map(x=>`<article class="name-card"><small>${ar(x.i+1)}</small><span>${esc(x.name)}</span></article>`).join('')||'<p class="empty">لا توجد نتيجة.</p>'}show();$('#name-search').oninput=e=>show(e.target.value)}
function tasbih(){const choices=['سبحان الله','الحمد لله','الله أكبر','لا إله إلا الله','أستغفر الله','لا حول ولا قوة إلا بالله','اللهم صل وسلم على نبينا محمد'];$('#main').innerHTML=heading('على مهل… اذكر الله','عدّاد شخصي للذكر. يحفظ العدد واختيارك على هذا الجهاز.','ذكرٌ يرافقك')+`<section class="tasbih"><label class="sr-only" for="tasbih-dhikr">اختر الذكر</label><select id="tasbih-dhikr">${choices.map(v=>`<option ${tasbihDhikr===v?'selected':''}>${v}</option>`).join('')}</select><div class="counter-orbit"><button class="counter-button" id="tasbih-tap" aria-label="إضافة تسبيحة"><strong id="tasbih-number">${ar(tasbihCount)}</strong><small>اضغط لذكرٍ جديد</small></button></div><p class="hint">الهدف الشخصي <label class="sr-only" for="tasbih-goal">هدف العدّاد</label><select id="tasbih-goal"><option value="33">٣٣</option><option value="100">١٠٠</option><option value="1000">١٠٠٠</option></select> <span id="goal-status"></span></p><div class="progress"><span id="tasbih-progress"></span></div><div class="toolbar" style="justify-content:center"><button class="chip" id="tasbih-undo">تراجع عن واحدة</button><button class="chip" id="tasbih-reset">بدء عدّ جديد</button></div><p class="hint">اختيار الهدف وسيلة للمتابعة، ولا يثبت به فضل أو عدد تعبدي مخصوص.</p></section>`;const update=()=>{$('#tasbih-number').textContent=ar(tasbihCount);const goal=Number($('#tasbih-goal').value);$('#tasbih-progress').style.width=Math.min(100,tasbihCount/goal*100)+'%';$('#goal-status').textContent=tasbihCount>=goal?'• اكتمل هدفك الشخصي ✓':'';write('tasbih',tasbihCount)};$('#tasbih-tap').onclick=()=>{tasbihCount++;update()};$('#tasbih-undo').onclick=()=>{tasbihCount=Math.max(0,tasbihCount-1);update()};$('#tasbih-reset').onclick=()=>{tasbihCount=0;update();toast('بدأ عدّ جديد')};$('#tasbih-goal').onchange=update;$('#tasbih-dhikr').onchange=e=>{tasbihDhikr=e.target.value;write('tasbihDhikr',tasbihDhikr)};update()}
function deeds(){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Muscat',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),saved=read('deeds',{}),done=saved.day===day?saved.done:[];$('#main').innerHTML=heading('خيرٌ صغير، وأثرٌ يبقى','قائمة يومية تعينك على التذكر والعمل. تُحفظ اختياراتك على جهازك وتبدأ من جديد كل يوم بتوقيت عُمان.','اعمل خيرًا')+`<div class="notice">هذه متابعة شخصية، وليست مقياسًا للأجر أو القبول. الإخلاص لله وحسن العمل هما المقصد.</div><p id="deeds-total"></p><section class="deeds-list">${DEEDS.map((d,i)=>`<label class="deed"><input type="checkbox" data-deed="${i}" ${done.includes(i)?'checked':''}><span><strong>${d[0]}</strong><small>${d[1]}</small></span></label>`).join('')}</section>`;const update=()=>{const checks=[...document.querySelectorAll('[data-deed]:checked')].map(x=>Number(x.dataset.deed));write('deeds',{day,done:checks});$('#deeds-total').textContent=`خطواتك اليوم: ${ar(checks.length)} من ${ar(DEEDS.length)}`};document.querySelectorAll('[data-deed]').forEach(c=>c.onchange=update);update()}
function sources(){$('#main').innerHTML=heading('سكينة… من عُمان إلى القلب','مساحة عربية مستقلة للقرآن والذكر والدعاء، تستلهم وقار العمارة العُمانية وألوان أرضها، وتعتز بهويتها الإباضية.','عن سكينة')+`<div class="source-grid"><article class="source-card"><h2>هويتنا ومنهجنا</h2><p>نقدم القرآن الكريم أصلًا جامعًا، ونفصل النص القرآني عن الحديث والدعاء العام. ونحيل مسائل الاعتقاد والفقه وخصوصيات المذهب الإباضي إلى المصادر المتخصصة وأهل العلم. لا تعني الهوية الإباضية أن جميع المرويات الحديثية هنا خضعت لمراجعة إباضية، ولا ننسب اعتمادًا أو إشرافًا إلى عالم أو جهة.</p><a href="https://iftaa.mara.gov.om/" target="_blank" rel="noopener">مكتب الإفتاء بسلطنة عُمان ↗</a><br><a href="https://www.mara.gov.om/" target="_blank" rel="noopener">وزارة الأوقاف والشؤون الدينية ↗</a></article><article class="source-card"><h2>المصحف الكريم</h2><p>المصحف محفوظ مع الموقع: ١١٤ سورة و٦٬٢٣٦ آية. استُورد نص الإصدار quran-uthmani من Al Quran Cloud كما هو، دون إعادة صياغة. بيانات السور والآيات من الخدمة نفسها. القراءة بالرسم العثماني، وليست صور صفحات مصحف ورقي.</p><a href="https://alquran.cloud/api" target="_blank" rel="noopener">المصدر: Al Quran Cloud ↗</a><br><a href="https://tanzil.net/" target="_blank" rel="noopener">مشروع تنزيل ↗</a><br><a href="QURAN-LICENSE.txt" target="_blank" rel="noopener">ترخيص نص القرآن وإشعار الحقوق ↗</a><p>التلاوة: مشاري العفاسي، عبر Islamic Network؛ تحتاج اتصالًا بالإنترنت. روابط السياق القرآني تحيل إلى Quran.com.</p></article><article class="source-card"><h2>الأذكار والأدعية</h2><p>مكتبة منتقاة قابلة للتوسع، لا ندعي أنها تحصر كل دعاء أو ذكر. يُذكر مرجع النص بجواره، وأرقام الأحاديث قد تختلف باختلاف الطبعات. روابط الأحاديث للمراجعة النصية ولا تمثل اعتمادًا مذهبيًا. الدعاء العام موسوم بوضوح، ولا تُنسب له فضائل أو أعداد خاصة.</p><p>عداد القراءة يبدأ من جديد مع كل جلسة. التكرارات المحددة تشير إلى المرجع المذكور؛ أما العدّاد الشخصي فوسيلة متابعة فقط.</p></article><article class="source-card"><h2>مصادر الاطلاع والإلهام</h2><p>اطلعنا على هذه المصادر لفهم التصنيف وتجربة الاستخدام. لم ننسخ مقالاتها أو تصميماتها.</p><p><a href="https://islamonline.net/أدعية-من-السنة-النبوية/" target="_blank" rel="noopener">إسلام أون لاين</a> • <a href="https://athkar.day/" target="_blank" rel="noopener">أذكار ديلي</a> • <a href="https://www.islambook.com/" target="_blank" rel="noopener">إسلام بوك</a> • <a href="https://kalemtayeb.com/adeiah/" target="_blank" rel="noopener">الكلم الطيب</a> • <a href="https://quran.com/ar" target="_blank" rel="noopener">Quran.com</a></p><p>الرقية هنا آيات ودعاء، وليست تشخيصًا أو بديلًا عن العلاج. قائمة الأسماء الحسنى هي القائمة المشهورة، مع التنبيه إلى أن تعيين الأسماء وعدّها محل بحث علمي.</p></article><article class="source-card"><h2>خصوصيتك وحفظ بياناتك</h2><p>المفضلة وعلامة القراءة والسبحة ومتابعة الأعمال محفوظة في متصفحك محليًا، ولا تُزامن مع أجهزة أخرى. حذف بيانات المتصفح يمحوها. الخطوط والتلاوات والروابط الخارجية تتصل بمزوديها عند استخدامها. لا توجد إعلانات أو أدوات تتبع أضفناها إلى الموقع.</p><button class="chip" id="export-data">تصدير بياناتي</button><label class="chip" style="cursor:pointer">استيراد بياناتي<input type="file" id="import-data" accept="application/json" class="sr-only"></label><p class="hint">نسخة احتياطية للمفضلة وموضع القراءة والعداد.</p></article><article class="source-card"><h2>العناية بالنص</h2><p>أُجري فحص بنيوي لاكتمال السور وعدد الآيات، ولا يُعد ذلك مراجعة شرعية للنصوص أو تخريجًا مستقلًا للأحاديث. للتصحيح والتوسع العلمي يُرجع إلى المصحف المعتمد والمراجع الأصلية وأهل الاختصاص.</p><p>هذه مبادرة مستقلة، لا تتبع وزارة الأوقاف أو مكتب الإفتاء أو أي موقع من المواقع المذكورة.</p></article></div>`;$('#export-data').onclick=()=>{const data={version:1,favorites,bookmark,tasbih:tasbihCount,tasbihDhikr};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sakinah-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import-data').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>100000)throw Error();const v=JSON.parse(await file.text());if(v.version!==1||!Array.isArray(v.favorites))throw Error();favorites=v.favorites.filter(id=>LIBRARY.some(d=>d.id===id));write('favorites',favorites);if(v.bookmark&&Number.isInteger(v.bookmark.s)&&v.bookmark.s>=1&&v.bookmark.s<=114&&Number.isInteger(v.bookmark.a)&&v.bookmark.a>=1&&v.bookmark.a<=(QURAN?.[v.bookmark.s-1].ayahs.length||0)){bookmark=v.bookmark;write('bookmark',bookmark)}if(typeof v.tasbihDhikr==='string'&&v.tasbihDhikr.length<100){tasbihDhikr=v.tasbihDhikr;write('tasbihDhikr',tasbihDhikr)}if(Number.isInteger(v.tasbih)&&v.tasbih>=0&&v.tasbih<1e9){tasbihCount=v.tasbih;write('tasbih',tasbihCount)}toast('استُعيدت بياناتك على هذا الجهاز')}catch{toast('تعذر استيراد الملف. اختر نسخة سكينة سليمة.')}}}
function route(){const hash=decodeURIComponent(location.hash.slice(1)||'home'),[path,query]=hash.split('?'),[r,p,a]=path.split('/');currentRoute=NAV.some(n=>n[0]===r)||r==='sources'?r:'home';document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===currentRoute;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');document.title=(NAV.find(n=>n[0]===currentRoute)?.[2]||'عن سكينة')+' | سكينة';if(currentRoute==='home')home();else if(currentRoute==='quran')renderQuran(p,a);else if(TITLES[currentRoute])collection(currentRoute,p);else if(currentRoute==='names')namesPage();else if(currentRoute==='tasbih')tasbih();else if(currentRoute==='deeds')deeds();else sources();if(!(currentRoute==='quran'&&a))window.scrollTo(0,0);const item=new URLSearchParams(query).get('item');if(item&&/^[a-zA-Z0-9\u0600-\u06ff]+$/.test(item))setTimeout(()=>document.getElementById('item-'+item)?.scrollIntoView({block:'center'}),80)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('نُسخ النص')}catch{toast('تعذر النسخ تلقائيًا؛ يمكنك تحديد النص ونسخه.')}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.route)location.hash=b.dataset.route;if(b.dataset.surah)location.hash='quran/'+b.dataset.surah;if(b.dataset.fav){const id=b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write('favorites',favorites);b.classList.toggle('faved',favorites.includes(id));b.textContent=favorites.includes(id)?'★':'☆';b.setAttribute('aria-pressed',favorites.includes(id));b.setAttribute('aria-label',favorites.includes(id)?'إزالة من المفضلة':'إضافة إلى المفضلة');if(currentRoute==='favorites'&&!favorites.includes(id))collection('favorites');toast(favorites.includes(id)?'حُفظ في المفضلة':'أُزيل من المفضلة')}if(b.dataset.copy||b.dataset.share){const d=LIBRARY.find(x=>x.id===(b.dataset.copy||b.dataset.share));if(!d)return;const text=textOf(d)+'\n'+d.reference;if(b.dataset.share&&navigator.share){try{await navigator.share({title:d.title,text,url:location.origin+location.pathname+'#'+d.section+'?item='+encodeURIComponent(d.id)})}catch(err){if(err.name!=='AbortError')copy(text)}}else copy(text)}if(b.dataset.count){const d=LIBRARY.find(x=>x.id===b.dataset.count);if(!d)return;counts[d.id]=Math.min(d.repeat,(counts[d.id]||0)+1);b.textContent=counts[d.id]>=d.repeat?'✓ تم':ar(counts[d.id])+' / '+ar(d.repeat);b.classList.toggle('done',counts[d.id]>=d.repeat)}if(b.dataset.bookmark){const [s,a]=b.dataset.bookmark.split(':').map(Number);bookmark={s,a};write('bookmark',bookmark);document.querySelectorAll('.ayah.bookmarked').forEach(el=>el.classList.remove('bookmarked'));b.closest('.ayah').classList.add('bookmarked');toast('حُفظ موضع القراءة على هذا الجهاز')}if(b.dataset.ayahCopy){const [s,a]=b.dataset.ayahCopy.split(':').map(Number);copy(QURAN[s-1].ayahs[a-1].text+'\n'+QURAN[s-1].name+' • '+ar(a))}if(b.dataset.searchLink!==undefined){$('#search-dialog').close();if(b.hash===location.hash)route()}});
$('#theme').onclick=()=>{document.body.classList.toggle('dark');write('dark',document.body.classList.contains('dark'));$('#theme').textContent=document.body.classList.contains('dark')?'☼':'☾'};
$('#menu').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',document.body.classList.contains('menu-open'))};document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar,#menu')){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}});
$('#search-open').onclick=()=>{$('#search-dialog').showModal();$('#global-search').focus()};$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-dialog').showModal();$('#global-search').focus()}});
let searchTimer;$('#global-search').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>search(e.target.value),180)};
function search(value){const term=normalize(value.trim());if(term.length<2){$('#search-results').innerHTML='<p class="hint">اكتب حرفين على الأقل للبحث.</p>';return}const found=LIBRARY.filter(d=>normalize(d.title+' '+d.category+' '+textOf(d)).includes(term)).slice(0,25);const verses=[];if(QURAN)for(const s of QURAN){for(const a of s.ayahs){if(normalize(a.text).includes(term))verses.push({s,a});if(verses.length>=40)break}if(verses.length>=40)break}$('#search-results').innerHTML=`<p class="hint">${ar(found.length)} نصًا • ${ar(verses.length)} آية${verses.length===40?' (أول ٤٠ نتيجة)':''}</p>`+found.map(d=>`<a class="search-result" href="#${d.section}?item=${encodeURIComponent(d.id)}" data-search-link><small>${esc(d.category)} • ${esc(d.title)}</small>${esc(textOf(d))}</a>`).join('')+verses.map(v=>`<a class="search-result" href="#quran/${v.s.number}/${v.a.numberInSurah}" data-search-link><small>${esc(v.s.name)} • الآية ${ar(v.a.numberInSurah)}</small><span style="font-family:Amiri;font-size:22px">${esc(v.a.text)}</span></a>`).join('')+(!found.length&&!verses.length?'<p class="empty">لم نعثر على نتيجة. جرّب كلمة أقصر.</p>':'')}
async function loadQuran(){quranError=false;try{const res=await fetch('quran-source.json');if(!res.ok)throw Error();const data=await res.json();if(data.data.surahs.length!==114||data.data.surahs.reduce((n,s)=>n+s.ayahs.length,0)!==6236)throw Error();QURAN=data.data.surahs;route()}catch{quranError=true;if(currentRoute==='quran')renderQuran();else toast('تعذر تحميل النص القرآني. افتح المصحف لإعادة المحاولة.')}}
window.addEventListener('hashchange',route);route();loadQuran();

